import re


_COUNSEL_HEADING_RE = re.compile(r"^\s*COUNSEL\s*$", re.IGNORECASE)
_APPELLEE_BLOCK_RE = re.compile(
    r"\bfor\s+"
    r"(?:Plaintiff|Plaintiffs|Defendant|Defendants|Respondent|Respondents|"
    r"Intervenor(?:-Defendant|-Respondent)?|Appellee|Appellees)"
    r"[^.\n]*\bAppellee(?:s)?\b",
    re.IGNORECASE,
)
_COUNSEL_LIST_HEADING_RE = re.compile(
    r"^\s*Counsel for\s+.*Appellee(?:s)?\s*:?\s*(.*)$", re.IGNORECASE
)
_MAJOR_STOP_HEADING_RE = re.compile(
    r"^\s*(?:OPINION|ORDER|SUMMARY|JUDGMENT|MEMORANDUM|BACKGROUND|INTRODUCTION|"
    r"DISCUSSION|CONCLUSION|PER CURIAM)\b",
    re.IGNORECASE,
)
_ORGANIZATION_WORD_RE = re.compile(
    r"\b(?:LLP|LLC|P\.C\.|PC|INC\.?|CORPORATION|COMPANY|DEPARTMENT|OFFICE|"
    r"UNIVERSITY|ASSOCIATION|GROUP|SERVICES|ATTORNEY|ATTORNEYS|COUNSEL|"
    r"LAWYERS|PARTNERS|BUDD|CLINIC|FOUNDATION|TRUST|COMMITTEE|AGENCY|"
    r"STATES ATTORNEY|UNITED STATES ATTORNEY)\b",
    re.IGNORECASE,
)


def _norm(text: str) -> str:
    return " ".join((text or "").split())


def _clean_name(text: str) -> str | None:
    text = _norm(text)
    if not text:
        return None
    # Remove a leading counsel-list label if one is present.
    text = re.sub(r"^\s*Counsel for\s+.*?Appellee(?:s)?\s*:?\s*", "", text, flags=re.IGNORECASE)
    text = text.strip()
    if not text:
        return None
    # The first attorney is typically the first comma-delimited token.
    candidate = text.split(",", 1)[0].strip()
    if " and " in candidate:
        candidate = candidate.split(" and ", 1)[0].strip()
    candidate = re.sub(r"\s*\([^)]*\)\s*$", "", candidate).strip(" ,;")
    candidate = candidate.strip()
    if not candidate or len(candidate) < 2:
        return None
    if ":" in candidate or "@" in candidate or _ORGANIZATION_WORD_RE.search(candidate):
        return None
    if len(candidate.split()) < 2:
        return None
    return candidate


def _line_dicts(doc: dict) -> list[dict]:
    lines = doc.get("lines") or []
    if lines:
        return lines
    text = doc.get("text") or ""
    out = []
    for i, raw in enumerate(text.splitlines(), start=1):
        out.append({"page_no": None, "line_no": i, "text": raw})
    return out


def _span_from_lines(lines: list[dict], start: int, end: int, text: str) -> dict:
    span = {"text": text}
    if 0 <= start < len(lines):
        page_no = lines[start].get("page_no")
        line_no = lines[start].get("line_no")
        if page_no is not None:
            span["page_no"] = page_no
        if line_no is not None:
            span["line_no"] = line_no
    return span


def _is_party_end(text: str) -> bool:
    compact = re.sub(r"\s+", "", text or "").lower()
    party_tokens = (
        "appellant",
        "appellants",
        "petitioner",
        "petitioners",
        "respondent",
        "respondents",
        "appellee",
        "appellees",
        "amicus",
        "amici",
        "intervenor",
        "plaintiff",
        "defendant",
    )
    if "for" in compact and any(token in compact for token in party_tokens):
        return True
    if len(compact) <= 60 and compact.endswith(".") and not any(ch in compact for ch in ",;:@") and any(
        token in compact for token in party_tokens
    ):
        return True
    return False


def _extract_from_standard_counsel(lines: list[dict]) -> list[dict]:
    counsel_idx = None
    for i, line in enumerate(lines):
        if _COUNSEL_HEADING_RE.match(_norm(line.get("text", ""))):
            counsel_idx = i
            break
    if counsel_idx is None:
        return []

    for end in range(counsel_idx + 1, len(lines)):
        raw = _norm(lines[end].get("text", ""))
        if not raw:
            continue
        if _MAJOR_STOP_HEADING_RE.match(raw):
            break

        window_start = max(counsel_idx + 1, end - 2)
        window = " ".join(
            _norm(lines[j].get("text", "")) for j in range(window_start, end + 1) if _norm(lines[j].get("text", ""))
        )
        compact = re.sub(r"\s+", "", window).lower()
        if "for" not in compact or "appellee" not in compact:
            continue

        start = end
        while start > counsel_idx + 1:
            prev = _norm(lines[start - 1].get("text", ""))
            if not prev:
                start -= 1
                continue
            if _MAJOR_STOP_HEADING_RE.match(prev):
                break
            if _is_party_end(prev):
                break
            start -= 1

        block = " ".join(
            _norm(lines[j].get("text", "")) for j in range(start, end + 1) if _norm(lines[j].get("text", ""))
        )
        name = _clean_name(block)
        if name:
            return [_span_from_lines(lines, start, end, name)]

    return []


def _extract_from_counsel_list(lines: list[dict]) -> list[dict]:
    for i, line in enumerate(lines):
        raw = line.get("text", "") or ""
        m = _COUNSEL_LIST_HEADING_RE.match(raw)
        if not m:
            continue
        tail = _norm(m.group(1))
        if tail:
            name = _clean_name(tail)
            if name:
                return [_span_from_lines(lines, i, i, name)]

        for j in range(i + 1, len(lines)):
            candidate = _norm(lines[j].get("text", ""))
            if not candidate:
                continue
            if candidate.startswith("*") or candidate.startswith("This summary constitutes"):
                continue
            if candidate.endswith(":"):
                continue
            if candidate and not candidate.lower().startswith("counsel for") and len(candidate) < 120:
                name = _clean_name(candidate)
                if name:
                    return [_span_from_lines(lines, j, j, name)]
            if _MAJOR_STOP_HEADING_RE.match(candidate):
                break
    return []


def rule_first_listed_attorney_representing_appellees(doc: dict) -> list[dict]:
    try:
        lines = _line_dicts(doc)
        spans = _extract_from_standard_counsel(lines)
        if spans:
            return spans
        return _extract_from_counsel_list(lines)
    except Exception:
        return []

import re


_COUNSEL_HEAD_RE = re.compile(
    r"(?:^|\n)\s*(?:COUNSEL|ATTORNEYS?)\s*(?:\n|$)",
    re.IGNORECASE,
)


def _as_int(value):
    try:
        return int(value)
    except Exception:
        return value


def _normalize(text: str) -> str:
    return re.sub(r"\s+", " ", (text or "")).strip()


def _iter_items(doc: dict):
    lines = doc.get("lines") or []
    if lines:
        items = [item for item in lines if isinstance(item, dict)]
        items = sorted(
            items,
            key=lambda x: (_as_int(x.get("page_no", 0)), _as_int(x.get("line_no", 0))),
        )
        for item in items:
            yield item
        return

    paragraphs = doc.get("paragraphs") or []
    if paragraphs:
        items = [item for item in paragraphs if isinstance(item, dict)]
        items = sorted(
            items,
            key=lambda x: (
                _as_int(x.get("page_no", 0)),
                _as_int(x.get("paragraph_no", 0)),
            ),
        )
        for item in items:
            yield item
        return

    pages = doc.get("pages") or []
    if pages:
        items = [item for item in pages if isinstance(item, dict)]
        items = sorted(items, key=lambda x: _as_int(x.get("page_no", 0)))
        for page in items:
            page_no = _as_int(page.get("page_no", 0))
            for line_no, raw_line in enumerate((page.get("text") or "").splitlines(), start=1):
                yield {"page_no": page_no, "line_no": line_no, "text": raw_line}


def _first_attorney_from_block(block_text: str) -> str:
    text = _normalize(block_text)
    if not text:
        return ""

    # Trim off affiliations and later counsel names, leaving the first person
    # in the block.
    text = text.split(";", 1)[0].strip()
    text = re.split(r"\s+\band\b\s+", text, 1, flags=re.IGNORECASE)[0].strip()
    text = text.split(",", 1)[0].strip()
    text = re.sub(
        r"\s*\((?:argued|lead|co[- ]?counsel|on brief|oral argument)\)\s*$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"\s*\([^)]*\)\s*$", "", text).strip()
    return text.strip(" ,;:")


def rule_first_listed_attorney_appellee(doc: dict) -> list[dict]:
    try:
        items = list(_iter_items(doc))
        if not items:
            return []

        in_counsel = False
        current_block = []

        for item in items:
            raw_text = item.get("text") or ""
            text = _normalize(raw_text)
            if not text:
                continue

            if not in_counsel:
                if _COUNSEL_HEAD_RE.search(raw_text):
                    in_counsel = True
                continue

            upper = text.upper()
            if upper.startswith("OPINION") or upper.startswith("SUMMARY"):
                break

            lower = text.lower()
            if any(
                keyword in lower
                for keyword in (
                    "appellant",
                    "appellee",
                    "amicus",
                    "amici",
                    "curiae",
                    "petitioner",
                    "respondent",
                )
            ):
                if lower.startswith("for "):
                    block_items = current_block[:]
                else:
                    current_block.append(item)
                    block_items = current_block[:]

                if "appellee" in lower:
                    block_text = "\n".join((x.get("text") or "") for x in block_items)
                    first = _first_attorney_from_block(block_text)
                    if first:
                        span = {"text": first}
                        for key in ("page_no", "line_no", "paragraph_no"):
                            if key in block_items[0]:
                                span[key] = block_items[0][key]
                        return [span]

                current_block = []
                continue

            current_block.append(item)

        return []
    except Exception:
        return []

import re


def rule_first_listed_attorney_appellant(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return " ".join((text or "").split())

        def compact(text: str) -> str:
            return re.sub(r"[^a-z]+", "", (text or "").lower())

        def line_dicts() -> list[dict]:
            lines = doc.get("lines") or []
            if lines:
                return [line for line in lines if isinstance(line, dict)]
            text = doc.get("text") or ""
            return [{"page_no": None, "line_no": i + 1, "text": raw} for i, raw in enumerate(text.splitlines())]

        def make_span(text: str, src: dict | None) -> dict:
            span = {"text": text}
            if isinstance(src, dict):
                if src.get("page_no") is not None:
                    span["page_no"] = src.get("page_no")
                if src.get("line_no") is not None:
                    span["line_no"] = src.get("line_no")
            return span

        def extract_caption_roles(lines: list[dict]) -> set[str]:
            role_aliases = {
                "appellant",
                "appellants",
                "petitioner",
                "petitioners",
                "portioner",
                "portioners",
            }
            role_patterns = (
                "plaintiff",
                "plaintiffs",
                "defendant",
                "defendants",
                "intervenor",
                "intervenors",
                "petitioner",
                "petitioners",
                "portioner",
                "portioners",
                "respondent",
                "respondents",
                "claimant",
                "claimants",
                "intervenordefendant",
                "intervenordefendants",
                "intervenorplaintiff",
                "intervenorplaintiffs",
                "intervenorrespondent",
                "intervenorrespondents",
                "intervenorpetitioner",
                "intervenorpetitioners",
            )
            for item in lines[:160]:
                text = compact(item.get("text", ""))
                if "appellant" not in text:
                    continue
                for pattern in role_patterns:
                    if pattern in text:
                        role_aliases.add(pattern)
            return role_aliases

        def is_major_heading(text: str) -> bool:
            return bool(
                re.match(
                    r"(?i)^\s*(?:OPINION|ORDER|SUMMARY|JUDGMENT|MEMORANDUM|BACKGROUND|INTRODUCTION|DISCUSSION|CONCLUSION|PER CURIAM)\b",
                    text or "",
                )
            )

        def is_counsel_heading(text: str) -> bool:
            return bool(re.match(r"(?i)^\s*(?:COUNSEL|ATTORNEYS?)\s*:?\s*$", text or ""))

        def first_attorney(block_text: str) -> str | None:
            text = norm(block_text)
            if not text:
                return None

            text = re.sub(r"(?i)^\s*counsel for\s+.*?:\s*", "", text).strip()
            text = re.sub(r"(?i),?\s*for\s+(?:the\s+)?(?:appellant|appellants)\b.*$", "", text).strip()
            candidate = text.split(";", 1)[0].strip()
            candidate = candidate.split(",", 1)[0].strip()
            candidate = re.split(r"(?i)\s+\band\b\s+", candidate, 1)[0].strip()
            candidate = re.sub(r"\s*\((?:argued|submitted|on brief|lead counsel|co-counsel|pro hac vice)\)\s*$", "", candidate, flags=re.IGNORECASE)
            candidate = re.sub(r"\s*\([^)]*\)\s*$", "", candidate).strip(" ,;:")

            if candidate and len(candidate.split()) >= 2:
                if not re.search(
                    r"(?i)\b(?:llp|llc|pc|p\.c\.|inc\.?|corporation|company|department|office|attorney|attorneys|counsel|group|association|clinic|services|partners|foundation|trust)\b",
                    candidate,
                ):
                    return candidate

            name_match = re.search(
                r"\b([A-Z][A-Za-z.'’\-]+(?:\s+[A-Z]\.)?(?:\s+[A-Z][A-Za-z.'’\-]+){1,4}(?:\s+Jr\.)?)\b",
                text,
            )
            if not name_match:
                return None
            fallback = norm(name_match.group(1)).strip(" ,;:")
            if len(fallback.split()) < 2:
                return None
            return fallback

        lines = line_dicts()
        if not lines:
            return []

        appellant_roles = extract_caption_roles(lines)
        generic_roles = {
            "appellant",
            "appellants",
            "appellee",
            "appellees",
            "plaintiff",
            "plaintiffs",
            "defendant",
            "defendants",
            "intervenor",
            "intervenors",
            "petitioner",
            "petitioners",
            "portioner",
            "portioners",
            "respondent",
            "respondents",
            "claimant",
            "claimants",
            "intervenordefendant",
            "intervenordefendants",
            "intervenorplaintiff",
            "intervenorplaintiffs",
            "intervenorrespondent",
            "intervenorrespondents",
            "intervenorpetitioner",
            "intervenorpetitioners",
            "amicus",
            "amici",
        }
        explicit_roles = {
            role
            for role in appellant_roles
            if role not in {"appellant", "appellants", "petitioner", "petitioners", "portioner", "portioners"}
        }
        target_roles = explicit_roles or {"petitioner", "petitioners", "portioner", "portioners"}

        def is_any_side_marker(text: str) -> bool:
            ctext = compact(text)
            if "for" not in ctext and not ctext.startswith("counselfor"):
                return False
            return any(f"for{role}" in ctext or f"counselfor{role}" in ctext for role in generic_roles)

        def marker_priority(text: str) -> int | None:
            ctext = compact(text)
            target_hit = any(
                role in ctext and (
                    f"for{role}" in ctext
                    or f"counselfor{role}" in ctext
                    or ctext.endswith(role)
                    or f"{role}appellant" in ctext
                    or f"{role}appellee" in ctext
                )
                for role in target_roles
            )
            direct_appellant = "appellant" in ctext and "crossappellant" not in ctext
            cross_appellant = "crossappellant" in ctext
            if target_hit and direct_appellant:
                return 0
            if target_hit and not cross_appellant:
                return 1
            if direct_appellant and not explicit_roles:
                return 2
            if target_hit and cross_appellant:
                return 3
            if cross_appellant and not explicit_roles:
                return 4
            if "appellee" in ctext and "appellant" not in ctext:
                return None
            if direct_appellant:
                return 5
            return None

        def block_result(block_start: int, block_end: int) -> list[dict]:
            start = block_start
            while start <= block_end and not norm(lines[start].get("text", "")):
                start += 1
            if start > block_end:
                return []

            block_lines = []
            for idx in range(start, block_end + 1):
                raw = norm(lines[idx].get("text", ""))
                if not raw:
                    continue
                if is_major_heading(raw) or is_counsel_heading(raw):
                    continue
                if raw.startswith("The Honorable "):
                    continue
                if re.fullmatch(r"\d+", raw):
                    continue
                if re.fullmatch(r"[A-Z][A-Z0-9 .,&'\-]{8,}", raw) and " V. " in raw:
                    continue
                block_lines.append(raw)
            if not block_lines:
                return []

            name = first_attorney(" ".join(block_lines))
            if not name:
                return []
            return [make_span(name, lines[start])]

        def is_side_marker_end(section_start: int, idx: int) -> bool:
