                target_aliases.add(compact(name))
        if 'realpartyininterest' in c or 'realpartyininterest' in c:
            target_roles.add('realpartyininterest')
            block = []
            for j in range(max(0, i - 4), i + 1):
                prev = caption_lines[j]
                if not prev:
                    continue
                if compact(prev) in {'v'}:
                    block = []
                    continue
                block.append(prev)
            name = clean_caption_name(block[:-1] if block else [])
            if name:
