    # add side-specific aliases from plaintiff-appellee criminal captions
    for txt in caption_lines[:40]:
        c = compact(txt)
        if 'plaintiffappellee' in c and 'unitedstates' in c:
            target_roles.add('plaintiff')
            target_aliases.add('unitedstates')
        if 'defendantappellee' in c:
            target_roles.add('defendant')
        if 'plaintiffsappellees' in c:
            target_roles.add('plaintiffs')
        if 'defendantsappellees' in c:
            target_roles.add('defendants')
