    segment = text.split(';', 1)[0].strip()
    segment = re.split(r'\\s+\\band\\b\\s+', segment, 1, flags=re.I)[0].strip()
    segment = segment.split(',', 1)[0].strip()
    segment = segment.strip(' ,;:')
    out = []
    if segment and len(segment.split()) >= 2:
        out.append(segment)
        stripped = re.sub(r'\\s*\\(["'^)]*'"\\)', '', segment).strip(' ,;:')
        if stripped and stripped "'!= segment:
            out.append(stripped)
    else:
        m = re.match(r"([A-Z][A-Za-z.'"'’\\-]+(?:\\s+[A-Z]\\.)?(?:\\s+[A-Z][A-Za-z.'’\\-]+){1,5}(?:\\s+\\(["'^)]*'"\\))?(?:\\s+(?:Jr\\.|II|III|IV))?)\", text)
        if m:
            seg = m.group(1).strip(' ,;:')
            out.append(seg)
            stripped = re.sub(r'\\s*\\(["'^)]*'"\\)', '', seg).strip(' ,;:')
            if stripped and stripped "'!= seg:
                out.append(stripped)
    cleaned = []
    seen = set()
    for cand in out:
        cc = compact(cand)
        if not cc or cc in seen:
            continue
        if len(cand.split()) < 2:
