        return None
    alias_hit = any(alias and alias in c for alias in target_aliases)
    role_hit = any(role in c for role in target_roles)
    has_appellee = 'appellee' in c or 'appellees' in c or 'crossappellee' in c
    has_resp = 'respondent' in c or 'respondents' in c or 'realpartyininterest' in c
    has_other_side = 'appellant' in c or 'appellants' in c or 'petitioner' in c or 'petitioners' in c or 'portioner' in c or 'portioners' in c
    if (role_hit or alias_hit) and (has_appellee or has_resp):
        return 0
    if role_hit or alias_hit:
        return 1 if not has_other_side else 2
    if (has_appellee or has_resp) and not has_other_side:
        return 3
    return None


def is_side_marker_end(lines, section_start, idx):
    current = norm(lines[idx].get('text', ''))
    if not current:
        return False
    cc = compact(current)
    if current.lower().startswith('counsel for ') or current.lower().startswith('for '):
        return True
    if any(role in cc for role in GENERIC_ROLES) and len(current.split()) <= 5 and not any(ch in current for ch in ',;:@'):
        return True
    if ';' in current and 'for' in cc and any(role in cc for role in GENERIC_ROLES):
        return True
    if idx > section_start:
        prev = norm(lines[idx - 1].get('text', ''))
        if prev and 'for' in compact(prev):
            combo = f'{prev} {current}'
            ccombo = compact(combo)
            if any(role in ccombo for role in GENERIC_ROLES):
                return True
    return False


