    block_lines = []
    src = None
    for idx in range(block_start, block_end + 1):
        raw = norm(lines[idx].get('text', ''))
        if not raw:
            continue
        if is_counsel_heading(raw) or heading_or_boundary(raw):
            continue
        if is_page_header(raw):
            continue
        if raw.startswith('The Honorable '):
            continue
        if raw.startswith('*') or raw.startswith('**') or raw.startswith('This summary constitutes'):
            continue
        if re.fullmatch(r'[\\d\\s]+', raw):
            continue
        if src is None:
            src = lines[idx]
        block_lines.append(raw)
    if not block_lines:
        return []
    cands = first_attorney_candidates(' '.join(block_lines))
    return [make_span(c, src) for c in cands]


def extract_from_counsel(lines, target_roles, target_aliases):
    counsel_indices = [i for i, item in enumerate(lines) if is_counsel_heading(norm(item.get('text', '')))]
    for counsel_idx in counsel_indices:
        section_end = len(lines)
        for j in range(counsel_idx + 1, len(lines)):
            txt = norm(lines[j].get('text', ''))
            if not txt:
                continue
            if is_counsel_heading(txt) or heading_or_boundary(txt):
                section_end = j
                break
        marker_indices = []
        windows = {}
        for end in range(counsel_idx + 1, section_end):
            if not is_side_marker_end(lines, counsel_idx + 1, end):
                continue
            pieces = [norm(lines[k].get('text', '')) for k in range(max(counsel_idx + 1, end - 1), end + 1) if norm(lines[k].get('text', ''))]
            window = ' '.join(pieces)
            marker_indices.append(end)
            windows[end] = window
        candidates = []
        prev_end = counsel_idx
        for end in marker_indices:
            pr = marker_priority(windows[end], target_roles, target_aliases)
            if pr is not None:
                spans = block_result(lines, prev_end + 1, end)
                if spans:
                    candidates.append((pr, end, spans))
            prev_end = end
        if candidates:
            candidates.sort(key=lambda x: (x[0], x[1]))
            return candidates[0][2]
    return []


def extract_from_info_labels(lines, target_roles, target_aliases):
    label_re = re.compile(r'(?i)"'^'"\\s*(?:counsel\\s+for|for)\\s+(.+?)(?::\\s*|(,\\s*)?"'$)'"')
    for i, item in enumerate(lines):
        raw = item.get('text', '') or ''
        txt = norm(raw)
        if not txt:
            continue
        m = label_re.match(txt)
        if not m:
            continue
        label = m.group(1)
        if marker_priority('for ' + label, target_roles, target_aliases) is None:
            continue
        tail = ''
        if ':' in txt:
            tail = txt.split(':', 1)[1].strip()
        if tail:
            spans = [make_span(c, item) for c in first_attorney_candidates(tail)]
            if spans:
                return spans
        for j in range(i + 1, min(i + 8, len(lines))):
            cand = norm(lines[j].get('text', ''))
            if not cand:
                continue
            if heading_or_boundary(cand) or is_counsel_heading(cand):
                break
            if label_re.match(cand) and j "'!= i + 1:
                break
            if cand.endswith('"':') or '@' in cand or re.search(r'\\b\\d{3}[)-]?\\d{3}\\b', cand):
                continue
            spans = [make_span(c, lines[j]) for c in first_attorney_candidates(cand)]
            if spans:
                return spans
    return []


def extract_from_info_paragraphs(lines, target_roles, target_aliases):
    for i, item in enumerate(lines):
        txt = norm(item.get('text', ''))
        if not txt or not INFO_CONTEXT_RE.search(txt):
            continue
        for j in range(i + 1, min(i + 80, len(lines))):
            cand = norm(lines[j].get('text', ''))
            if not cand:
                continue
            if heading_or_boundary(cand) and j > i + 1:
                break
            if marker_priority(cand, target_roles, target_aliases) is None:
                continue
            spans = [make_span(c, lines[j]) for c in first_attorney_candidates(cand)]
            if spans:
                return spans
    return []


def extract_from_caption(lines, target_roles, caption_fallbacks):
    # use target caption name only when no counsel-style info exists
    has_counselish = any(is_counsel_heading(norm(x.get('text',''))) or INFO_CONTEXT_RE.search(norm(x.get('text',''))) for x in lines[:220])
    if has_counselish:
        return []
    for name in caption_fallbacks:
        if len(name.split()) >= 2 and not ORG_RE.search(name):
            return [make_span(name, lines[0])]
    return []


def rule(doc):
    lines = doc['lines']
    target_roles, target_aliases, caption_fallbacks = extract_targets(lines)
    spans = extract_from_counsel(lines, target_roles, target_aliases)
    if spans:
        return spans
    spans = extract_from_info_labels(lines, target_roles, target_aliases)
    if spans:
        return spans
    spans = extract_from_info_paragraphs(lines, target_roles, target_aliases)
    if spans:
        return spans
    spans = extract_from_caption(lines, target_roles, caption_fallbacks)
    if spans:
        return spans
    return [{'text': 'NOT FOUND'}]

correct = 0
wrong = []
for d in obj['documents']:
    text = Path(d['doc_path']).read_text(errors='ignore')
    doc = {'doc_name': d['doc_name'], 'text': text, 'lines': line_dicts(text)}
    preds = [x.get('text') for x in rule(doc)]
    if d['ground_truth'] in preds:
        correct += 1
    else:
        wrong.append((d['doc_name'], d['ground_truth'], preds[:4]))
print('accuracy', correct, '/', len(obj['documents']), '=', round(correct/len(obj['documents']), 4))
print('wrong count', len(wrong))
print(json.dumps(wrong[:60], indent=2))
